import crypto from 'node:crypto';
import { test, expect } from '../support/fixtures';
import { OwnerFormPage, ownerData } from '../pages/owner-pages';
import { PetFormPage, PetDetailsComponent } from '../pages/pet-pages';
import { VisitPage } from '../pages/visit-page';

test("E2E-040 Book tomorrow visit", async ({ page, evidence }) => {
  const owner = new OwnerFormPage(page);
  const detail = new PetDetailsComponent(page);
  const pet = new PetFormPage(page);
  const visit = new VisitPage(page);
  const ownerValues = ownerData(crypto.randomUUID().replaceAll('-', '').slice(0, 15));
  await evidence.step("E2E-040", "E2E-040-01", "Open new owner form", async () => { await owner.openNew(); });
  await evidence.assert("E2E-040", "E2E-040-01", "Owner form is visible — await expect(owner.heading).toBeVisible();", async () => { await expect(owner.heading).toBeVisible(); }, async () => owner.heading.textContent());
  await evidence.step("E2E-040", "E2E-040-02", "Enter unique owner data", async () => { await owner.enterOwner(ownerValues); });
  await evidence.assert("E2E-040", "E2E-040-02", "Last name retains unique input — await expect(owner.fields.lastName).toHaveValue(ownerValues.lastName);", async () => { await expect(owner.fields.lastName).toHaveValue(ownerValues.lastName); }, async () => owner.fields.lastName.inputValue());
  await evidence.step("E2E-040", "E2E-040-03", "Create isolated owner", async () => { await owner.submit(); });
  await evidence.assert("E2E-040", "E2E-040-03", "Owner details include unique surname — await expect(detail.heading).toBeVisible();", async () => { await expect(detail.heading).toBeVisible(); }, async () => detail.heading.textContent());
  await evidence.assert("E2E-040", "E2E-040-03", "Owner details include unique surname — await expect(page).toHaveURL(/\\/owners\\/\\d+(?:;jsessionid=[\\w]+)?$/);", async () => { await expect(page).toHaveURL(/\/owners\/\d+(?:;jsessionid=[\w]+)?$/); }, async () => ({ url: page.url() }));
  await evidence.step("E2E-040", "E2E-040-04", "Open Add New Pet", async () => { await detail.addPet(); });
  await evidence.assert("E2E-040", "E2E-040-04", "New Pet form is visible — await expect(pet.heading).toBeVisible();", async () => { await expect(pet.heading).toBeVisible(); }, async () => pet.heading.textContent());
  await evidence.step("E2E-040", "E2E-040-05", "Enter pet name, birth date and type", async () => { await pet.enterPet({"name":"Alpha","birthDate":"2020-01-02","type":"dog"}); });
  await evidence.assert("E2E-040", "E2E-040-05", "Pet inputs retain supplied values — await expect(pet.name).toHaveValue(\"Alpha\");", async () => { await expect(pet.name).toHaveValue("Alpha"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.assert("E2E-040", "E2E-040-05", "Pet inputs retain supplied values — await expect(pet.birthDate).toHaveValue(\"2020-01-02\");", async () => { await expect(pet.birthDate).toHaveValue("2020-01-02"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.assert("E2E-040", "E2E-040-05", "Pet inputs retain supplied values — await expect(pet.type).toHaveValue(\"dog\");", async () => { await expect(pet.type).toHaveValue("dog"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.step("E2E-040", "E2E-040-06", "Submit new pet", async () => { await pet.submit(); });
  await evidence.assert("E2E-040", "E2E-040-06", "Pet is persisted in owner details — await expect(detail.pet(\"Alpha\")).toContainText('2020-01-02');", async () => { await expect(detail.pet("Alpha")).toContainText('2020-01-02'); }, async () => await detail.pets.allTextContents());
  await evidence.step("E2E-040", "E2E-040-07", "Open Add Visit", async () => { await detail.addVisit("Alpha"); });
  await evidence.assert("E2E-040", "E2E-040-07", "New Visit form is visible — await expect(visit.heading).toBeVisible();", async () => { await expect(visit.heading).toBeVisible(); }, async () => visit.heading.textContent());
  const tomorrow = (await visit.minimumDate())!;
  const today = new Date(Date.parse(tomorrow) - 86400000).toISOString().slice(0,10);
  const past = new Date(Date.parse(tomorrow) - 172800000).toISOString().slice(0,10);
  await evidence.step("E2E-040", "E2E-040-08", "Enter visit date and description", async () => { await visit.enterVisit(tomorrow, "E2E preventive examination"); });
  await evidence.assert("E2E-040", "E2E-040-08", "Visit inputs retain entered values — await expect(visit.date).toHaveValue(tomorrow);", async () => { await expect(visit.date).toHaveValue(tomorrow); }, async () => ({ date: await visit.date.inputValue(), description: await visit.description.inputValue() }));
  await evidence.assert("E2E-040", "E2E-040-08", "Visit inputs retain entered values — await expect(visit.description).toHaveValue(\"E2E preventive examination\");", async () => { await expect(visit.description).toHaveValue("E2E preventive examination"); }, async () => ({ date: await visit.date.inputValue(), description: await visit.description.inputValue() }));
  await evidence.step("E2E-040", "E2E-040-09", "Book visit", async () => { await visit.submit(); });
  await evidence.assert("E2E-040", "E2E-040-09", "Booked visit appears in owner details — await expect(detail.heading).toBeVisible();", async () => { await expect(detail.heading).toBeVisible(); }, async () => detail.heading.textContent());
  await evidence.assert("E2E-040", "E2E-040-09", "Booked visit appears in owner details — await expect(detail.visit(\"E2E preventive examination\")).toBeVisible();", async () => { await expect(detail.visit("E2E preventive examination")).toBeVisible(); }, async () => detail.visit("E2E preventive examination").allTextContents());
});

